export const LOCATION_HYPNOSIS_FIELD_ID='location-hypnosis-effects';
export const LOCATION_HYPNOSIS_AUTH_FILE='services/location-hypnosis-authorizations.json';
export const LOCATION_HYPNOSIS_CONTRACT='地点催眠（含封闭空间group与开放空间location指令）只属于所选地点对象的 /values/location-hypnosis-effects 记录，不属于人物，不写MVU /规则。暂存没有效果；真实发送后仅创建status=pending的命令候选，不代表剧情成功。只对本轮已发送并授权的pending行使用ObjectUpdate整record replace，将status改为active或failed，并写effect/reason；必须完整保留记录其它行和该行固定requestId、commandId、owner、lifetime、startTime、endTime。active要求实际剧情成功且effect非空；失败写failed、effect为空。不许新建未授权key、删除历史、修改地点/开始/截止/永久属性、为重试延长时限或把范围作用复制到人物临时/永久效果。active只在所属地点及子地点、且固定截止前应用，离开后不会成为人物残留；已过期和历史行只读。双胞胎与林安始终不受催眠APP影响。MC仍从应用账户唯一余额按实际剧情成功结算，不能由地点属性补能量或改上限。';
