export function locationHypnosisOwner(request){const ref=request?.location?.objectRef??request?.effectOwner??request?.location;if(!ref||ref.kind&&ref.kind!=='location'||typeof ref.id!=='string'||!ref.id||request.location?.id&&request.location.id!==ref.id)throw Error('地点催眠必须绑定真实地点对象');return normalizeRef({kind:'location',id:ref.id},'location');}
