export async function registerLocationHypnosisUserMessage(runtime,message,{promptAnchor,system=null}={}){if(!(message?.is_user===true||message?.role==='user'))return{registered:0};const text=String(message.mes??message.message??message.content??''),block=text.match(/<玩家日程>([\s\S]*?)<\/玩家日程>/)?.[1];if(block){const packet=JSON.parse(block);return registerSentLocationHypnosis(runtime,packet,{promptAnchor});}const drafts=await runtime.store.readJson('services/location-hypnosis-staged.json',{}),auth=await locationHypnosisAuthorizations(runtime);let total=0;for(const [marker,action]of Object.entries(drafts)){if(!text.includes(marker)||Object.values(auth.requests).some(row=>row.template.requestId.startsWith(marker+'-')))continue;if(!system)continue;const clock=storyClock(system),index=Math.floor((Number(clock.time.slice(0,2))*60+Number(clock.time.slice(3)))/120),packet={type:'schedule',date:clock.date,start:clock.time,cells:[{index,attachments:[action],actions:[]}]};total+=(await registerSentLocationHypnosis(runtime,packet,{promptAnchor})).registered;}return{registered:total};}
